/* Minimal styling for playable snake — Ticket 1 */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  background: #111;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: sans-serif;
  color: #fff;
}

#game-container {
  position: relative;
}

#game-canvas {
  display: block;
  background: #000;
  border: 1px solid #333;
}

#overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.7);
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.2em;
}

#game-over {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

#game-over h2 {
  font-size: 1.5em;
}

#game-over button {
  padding: 8px 20px;
  font-size: 1em;
  cursor: pointer;
  background: #222;
  color: #fff;
  border: 1px solid #555;
  border-radius: 4px;
}

#game-over button:hover {
  background: #333;
}

/**
 * Snake Game — Ticket 1: Minimal playable snake
 * Grid rendered on canvas, snake moves and changes direction via keyboard.
 * Food spawns randomly; eating grows snake and increments score.
 * Wall/self collision ends game with "Game Over" and "Play Again".
 */

// ─── Constants ──────────────────────────────────────────────
const BOARD_SIZE = 20;         // default grid cells per row/column
const CELL_SIZE = 20;          // pixels per cell (fixed for minimal version)
const TICK_MS = 150;           // game tick interval in milliseconds

// Directions
const DIR = {
  UP:    { x:  0, y: -1 },
  DOWN:  { x:  0, y:  1 },
  LEFT:  { x: -1, y:  0 },
  RIGHT: { x:  1, y:  0 },
};

// ─── DOM References ─────────────────────────────────────────
const canvas = document.getElementById('game-canvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const gameOverDiv = document.getElementById('game-over');
const finalScoreEl = document.getElementById('final-score');
const playAgainBtn = document.getElementById('play-again-btn');

// ─── Canvas Sizing ──────────────────────────────────────────
canvas.width = BOARD_SIZE * CELL_SIZE;
canvas.height = BOARD_SIZE * CELL_SIZE;

// ─── Game State ─────────────────────────────────────────────
let snake = [];           // array of {x, y}, head is index 0
let direction = DIR.RIGHT;       // current movement direction
let nextDirection = DIR.RIGHT;   // buffered direction (applied on next tick)
let food = { x: 0, y: 0 };      // food position
let score = 0;
let gameRunning = false;
let gameStarted = false;
let gameOverState = false;
let lastTick = 0;
let animFrameId = null;

// ─── Initialization ─────────────────────────────────────────

/**
 * Place food at a random cell not occupied by the snake.
 */
function placeFood() {
  const occupied = new Set(snake.map(s => `${s.x},${s.y}`));
  let x, y;
  do {
    x = Math.floor(Math.random() * BOARD_SIZE);
    y = Math.floor(Math.random() * BOARD_SIZE);
  } while (occupied.has(`${x},${y}`));
  food = { x, y };
}

/**
 * Reset the game state to initial values (ready to start).
 */
function resetGame() {
  const center = Math.floor(BOARD_SIZE / 2);
  // Snake starts at center, length 3, heading right
  snake = [
    { x: center, y: center },
    { x: center - 1, y: center },
    { x: center - 2, y: center },
  ];
  direction = DIR.RIGHT;
  nextDirection = DIR.RIGHT;
  score = 0;
  placeFood();
  gameOverState = false;
  gameRunning = false;
  gameStarted = false;
}

// ─── Drawing ────────────────────────────────────────────────

/**
 * Draw a single cell as a filled rectangle with a small gap for grid effect.
 */
function drawCell(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * CELL_SIZE + 1, y * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
}

/**
 * Render the entire game frame.
 */
function render() {
  // Clear canvas
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw food
  drawCell(food.x, food.y, '#f00');

  // Draw snake head
  drawCell(snake[0].x, snake[0].y, '#0f0');

  // Draw snake body
  for (let i = 1; i < snake.length; i++) {
    drawCell(snake[i].x, snake[i].y, '#0a0');
  }
}

// ─── Game Logic ─────────────────────────────────────────────

/**
 * Check if a position is occupied by the snake.
 */
function isOccupied(x, y) {
  return snake.some(s => s.x === x && s.y === y);
}

/**
 * Step the game forward by one tick.
 */
function tick() {
  // Apply buffered direction
  direction = nextDirection;

  // Calculate new head position
  const head = snake[0];
  const newHead = {
    x: head.x + direction.x,
    y: head.y + direction.y,
  };

  // Wall collision check
  if (newHead.x < 0 || newHead.x >= BOARD_SIZE ||
      newHead.y < 0 || newHead.y >= BOARD_SIZE) {
    endGame();
    return;
  }

  // Self collision check (check against all body segments except tail,
  // since the tail will move unless food is eaten)
  // We check against all segments except the very last one if no food eaten.
  // But if food IS eaten, the tail stays, so we check all.
  // Simple approach: check all segments; if tail moves, it won't collide.
  const eating = newHead.x === food.x && newHead.y === food.y;

  if (!eating) {
    // Tail will move, so it's safe to ignore the last segment
    for (let i = 0; i < snake.length - 1; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }
  } else {
    // Eating food — check all segments since tail won't move
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }
  }

  // Move snake: prepend new head
  snake.unshift(newHead);

  // Check if food eaten
  if (eating) {
    score++;
    placeFood();
  } else {
    // Remove tail
    snake.pop();
  }
}

/**
 * End the game.
 */
function endGame() {
  gameRunning = false;
  gameOverState = true;
  finalScoreEl.textContent = 'Score: ' + score;
  gameOverDiv.style.display = 'flex';
  render();
}

// ─── Game Loop ──────────────────────────────────────────────

/**
 * Main game loop using requestAnimationFrame.
 * Only processes a tick when enough time has passed.
 */
function gameLoop(timestamp) {
  if (!gameRunning) return;

  animFrameId = requestAnimationFrame(gameLoop);

  if (timestamp - lastTick >= TICK_MS) {
    lastTick = timestamp;
    tick();
    render();
  }
}

/**
 * Start the game loop.
 */
function startGameLoop() {
  gameRunning = true;
  gameOverState = false;
  lastTick = performance.now();
  render();
  animFrameId = requestAnimationFrame(gameLoop);
}

// ─── Input Handling ─────────────────────────────────────────

/**
 * Opposite directions that cannot be combined.
 */
function isOpposite(a, b) {
  return a.x === -b.x && a.y === -b.y;
}

/**
 * Handle keydown events for game input.
 */
function handleKeyDown(e) {
  // Prevent page scrolling from arrow keys
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
    e.preventDefault();
  }

  // If game hasn't started yet (overlay showing), any key starts it
  if (!gameStarted && !gameRunning && !gameOverState) {
    overlay.style.display = 'none';
    gameStarted = true;
    startGameLoop();
    return;
  }

  // If game over, ignore input (use button to restart)
  if (gameOverState) return;

  // Direction controls
  switch (e.key) {
    case 'ArrowUp':
    case 'w':
    case 'W':
      if (!isOpposite(DIR.UP, direction)) nextDirection = DIR.UP;
      break;
    case 'ArrowDown':
    case 's':
    case 'S':
      if (!isOpposite(DIR.DOWN, direction)) nextDirection = DIR.DOWN;
      break;
    case 'ArrowLeft':
    case 'a':
    case 'A':
      if (!isOpposite(DIR.LEFT, direction)) nextDirection = DIR.LEFT;
      break;
    case 'ArrowRight':
    case 'd':
    case 'D':
      if (!isOpposite(DIR.RIGHT, direction)) nextDirection = DIR.RIGHT;
      break;
  }
}

// ─── Play Again Button ──────────────────────────────────────

playAgainBtn.addEventListener('click', () => {
  gameOverDiv.style.display = 'none';
  resetGame();
  overlay.style.display = 'flex';
  gameStarted = false;
  render();
});

// ─── Event Listeners ────────────────────────────────────────
document.addEventListener('keydown', handleKeyDown);

// ─── Expose game state on `window` for debugging/testing ────
window.snakeGame = {
  getSnake: () => [...snake],
  getDirection: () => direction,
  getNextDirection: () => nextDirection,
  getFood: () => ({ ...food }),
  getScore: () => score,
  getGameRunning: () => gameRunning,
  getBoardSize: () => BOARD_SIZE,
  tick: tick,
  reset: resetGame,
};

// Initial render
resetGame();
render();

