  }

  // If game over or start menu visible, ignore input
  if (gameOverState || startMenu.style.display !== 'none') return;

  // Direction controls
  switch (e.key) {
    case 'ArrowUp':
    case 'w':
    case 'W':
      if (!isOpposite(DIR.UP, direction)) nextDirection = DIR.UP;
      break;
    case 'ArrowDown':
    case 's':
