const finalHighScoreEl = document.getElementById('final-high-score');
const playAgainBtn = document.getElementById('play-again-btn');

// ─── Constants ──────────────────────────────────────────────
const TICK_MS = 150;           // game tick interval in milliseconds
const MIN_CELL_SIZE = 12;      // minimum pixel size per cell

const DIR = {
  UP:    { x:  0, y: -1 },
  DOWN:  { x:  0, y:  1 },
  LEFT:  { x: -1, y:  0 },
  RIGHT: { x:  1, y:  0 },
};

// ─── Session State ──────────────────────────────────────────
let sessionHighScore = 0;       // resets on page reload
let configuredBoardSize = 20;   // user-selected board size
let boardSize = 20;             // effective board size (viewport-capped)
let cellSize = 20;              // computed pixel size per cell

// ─── Game State ─────────────────────────────────────────────
let snake = [];
let direction = DIR.RIGHT;
let nextDirection = DIR.RIGHT;
let food = { x: 0, y: 0 };
let score = 0;
let gameRunning = false;
let gameStarted = false;
let gameOverState = false;
let lastTick = 0;
