 * Show the start menu, hide the game area.
 */
function showStartMenu() {
  startMenu.style.display = 'flex';
  gameArea.style.display = 'none';
  updateScoreDisplay();
  // Render a blank canvas when start menu is shown
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

/**
 * Hide the start menu, show the game area.
 */
function showGameArea() {
  startMenu.style.display = 'none';
  gameArea.style.display = 'block';
  updateScoreDisplay();
  computeBoardDimensions();
}

// ─── Food ───────────────────────────────────────────────────

/**
 * Place food at a random cell not occupied by the snake.
 */
function placeFood() {
  const occupied = new Set(snake.map(s => `${s.x},${s.y}`));
  let x, y;
  do {
    x = Math.floor(Math.random() * boardSize);
    y = Math.floor(Math.random() * boardSize);
  } while (occupied.has(`${x},${y}`));
  food = { x, y };
}

// ─── Initialization ─────────────────────────────────────────

/**
 * Reset the game state to initial values (ready to start).
 */
function resetGame() {
  const center = Math.floor(boardSize / 2);
  snake = [
    { x: center, y: center },
    { x: center - 1, y: center },
    { x: center - 2, y: center },
  ];
  direction = DIR.RIGHT;
  nextDirection = DIR.RIGHT;
  score = 0;
  placeFood();
  gameOverState = false;
  gameRunning = false;
  gameStarted = false;
  updateScoreDisplay();
}

