/**
 * Snake Game — Ticket 2: Start menu + score system
 *
 * Start menu with title, board size input (default 20, min 10, viewport-capped),
 * session high-score display, and "Start Game" button.
 * "Press any key to start" overlay after clicking Start Game.
 * Real-time score display during play.
 * Game-over screen showing final score, session high-score, and "Play Again".
 * Session high-score resets on page reload (no localStorage).
 */

// ─── DOM References ─────────────────────────────────────────
const startMenu = document.getElementById('start-menu');
const gameArea = document.getElementById('game-area');
const boardSizeInput = document.getElementById('board-size-input');
const highScoreDisplay = document.getElementById('high-score-display');
const startBtn = document.getElementById('start-btn');
const scoreBar = document.getElementById('score-bar');
const scoreLabel = document.getElementById('score-label');
const highScoreLabel = document.getElementById('high-score-label');
const canvas = document.getElementById('game-canvas');
const ctx = canvas.getContext('2d');
const overlay = document.getElementById('overlay');
const gameOverDiv = document.getElementById('game-over');
const finalScoreEl = document.getElementById('final-score');
const finalHighScoreEl = document.getElementById('final-high-score');
const playAgainBtn = document.getElementById('play-again-btn');

// ─── Constants ──────────────────────────────────────────────
const TICK_MS = 150;           // game tick interval in milliseconds
const MIN_CELL_SIZE = 12;      // minimum pixel size per cell

const DIR = {
  UP:    { x:  0, y: -1 },
  DOWN:  { x:  0, y:  1 },
  LEFT:  { x: -1, y:  0 },
  RIGHT: { x:  1, y:  0 },
};

// ─── Session State ──────────────────────────────────────────
let sessionHighScore = 0;       // resets on page reload
let configuredBoardSize = 20;   // user-selected board size
let boardSize = 20;             // effective board size (viewport-capped)
let cellSize = 20;              // computed pixel size per cell

// ─── Game State ─────────────────────────────────────────────
let snake = [];
let direction = DIR.RIGHT;
let nextDirection = DIR.RIGHT;
let food = { x: 0, y: 0 };
let score = 0;
let gameRunning = false;
let gameStarted = false;
let gameOverState = false;
let lastTick = 0;
let animFrameId = null;

// ─── Board Size Calculation ─────────────────────────────────

/**
 * Compute the effective board size and cell size based on viewport.
 * The board must fit within the viewport minus the score bar height and padding.
 * Cell size is capped to be at least MIN_CELL_SIZE pixels.
 */
function computeBoardDimensions() {
  // Available area: viewport minus score bar and padding
  const scoreBarHeight = 36;
  const padding = 40;
  const availableWidth = window.innerWidth - padding;
  const availableHeight = window.innerHeight - scoreBarHeight - padding;

  // Calculate max board size that keeps cells at least MIN_CELL_SIZE
  const maxByWidth = Math.floor(availableWidth / MIN_CELL_SIZE);
  const maxByHeight = Math.floor(availableHeight / MIN_CELL_SIZE);
  const viewportMax = Math.min(maxByWidth, maxByHeight);

  // Use the configured size, but cap at viewport maximum (minimum 10)
  boardSize = Math.max(10, Math.min(configuredBoardSize, viewportMax));

  // Recalculate cell size to fit
  const cellByWidth = Math.floor(availableWidth / boardSize);
  const cellByHeight = Math.floor(availableHeight / boardSize);
  cellSize = Math.max(MIN_CELL_SIZE, Math.min(cellByWidth, cellByHeight));

  // Canvas size
  canvas.width = boardSize * cellSize;
  canvas.height = boardSize * cellSize;
}

/**
 * Update the board size input to reflect the capping.
 */
function updateBoardSizeInput() {
  computeBoardDimensions();
  if (configuredBoardSize !== boardSize) {
    boardSizeInput.title = `Viewport caps board size to ${boardSize}`;
  } else {
    boardSizeInput.title = '';
  }
}

// ─── UI Helpers ─────────────────────────────────────────────

/**
 * Update all score-related UI elements.
 */
function updateScoreDisplay() {
  scoreLabel.textContent = `Score: ${score}`;
  highScoreDisplay.textContent = sessionHighScore;
  highScoreLabel.textContent = `Best: ${sessionHighScore}`;
}

/**
 * Show the start menu, hide the game area.
 */
function showStartMenu() {
  startMenu.style.display = 'flex';
  gameArea.style.display = 'none';
  updateScoreDisplay();
  // Render a blank canvas when start menu is shown
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

/**
 * Hide the start menu, show the game area.
 */
function showGameArea() {
  startMenu.style.display = 'none';
  gameArea.style.display = 'block';
  updateScoreDisplay();
  computeBoardDimensions();
}

// ─── Food ───────────────────────────────────────────────────

/**
 * Place food at a random cell not occupied by the snake.
 */
function placeFood() {
  const occupied = new Set(snake.map(s => `${s.x},${s.y}`));
  let x, y;
  do {
    x = Math.floor(Math.random() * boardSize);
    y = Math.floor(Math.random() * boardSize);
  } while (occupied.has(`${x},${y}`));
  food = { x, y };
}

// ─── Initialization ─────────────────────────────────────────

/**
 * Reset the game state to initial values (ready to start).
 */
function resetGame() {
  const center = Math.floor(boardSize / 2);
  snake = [
    { x: center, y: center },
    { x: center - 1, y: center },
    { x: center - 2, y: center },
  ];
  direction = DIR.RIGHT;
  nextDirection = DIR.RIGHT;
  score = 0;
  placeFood();
  gameOverState = false;
  gameRunning = false;
  gameStarted = false;
  updateScoreDisplay();
}

// ─── Drawing ────────────────────────────────────────────────

/**
 * Draw a single cell as a filled rectangle with a small gap for grid effect.
 */
function drawCell(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * cellSize + 1, y * cellSize + 1, cellSize - 2, cellSize - 2);
}

/**
 * Render the entire game frame.
 */
function render() {
  // Clear canvas
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw food
  drawCell(food.x, food.y, '#f00');

  // Draw snake head
  drawCell(snake[0].x, snake[0].y, '#0f0');

  // Draw snake body
  for (let i = 1; i < snake.length; i++) {
    drawCell(snake[i].x, snake[i].y, '#0a0');
  }
}

// ─── Game Logic ─────────────────────────────────────────────

/**
 * Step the game forward by one tick.
 */
function tick() {
  // Apply buffered direction
  direction = nextDirection;

  // Calculate new head position
  const head = snake[0];
  const newHead = {
    x: head.x + direction.x,
    y: head.y + direction.y,
  };

  // Wall collision check
  if (newHead.x < 0 || newHead.x >= boardSize ||
      newHead.y < 0 || newHead.y >= boardSize) {
    endGame();
    return;
  }

  // Self collision check
  const eating = newHead.x === food.x && newHead.y === food.y;

  if (!eating) {
    for (let i = 0; i < snake.length - 1; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }
  } else {
    for (let i = 0; i < snake.length; i++) {
      if (snake[i].x === newHead.x && snake[i].y === newHead.y) {
        endGame();
        return;
      }
    }
  }

  // Move snake: prepend new head
  snake.unshift(newHead);

  if (eating) {
    score++;
    // Update session high score
    if (score > sessionHighScore) {
      sessionHighScore = score;
    }
    updateScoreDisplay();
    placeFood();
  } else {
    snake.pop();
  }
}

/**
 * End the game.
 */
function endGame() {
  gameRunning = false;
  gameOverState = true;
  finalScoreEl.textContent = `Score: ${score}`;
  finalHighScoreEl.textContent = `High Score: ${sessionHighScore}`;
  gameOverDiv.style.display = 'flex';
  render();
}

// ─── Game Loop ──────────────────────────────────────────────

/**
 * Main game loop using requestAnimationFrame.
 * Only processes a tick when enough time has passed.
 */
function gameLoop(timestamp) {
  if (!gameRunning) return;

  animFrameId = requestAnimationFrame(gameLoop);

  if (timestamp - lastTick >= TICK_MS) {
    lastTick = timestamp;
    tick();
    render();
  }
}

/**
 * Start the game loop.
 */
function startGameLoop() {
  gameRunning = true;
  gameOverState = false;
  lastTick = performance.now();
  render();
  animFrameId = requestAnimationFrame(gameLoop);
}

// ─── Input Handling ─────────────────────────────────────────

/**
 * Opposite directions that cannot be combined.
 */
function isOpposite(a, b) {
  return a.x === -b.x && a.y === -b.y;
}

/**
 * Handle keydown events for game input.
 */
function handleKeyDown(e) {
  // Prevent page scrolling from arrow keys and space
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(e.key)) {
    e.preventDefault();
  }

  // If start menu is visible, ignore all input
  if (startMenu.style.display !== 'none') return;

  // If game hasn't started yet (overlay showing), any key starts it
  if (!gameStarted && !gameRunning && !gameOverState && overlay.style.display === 'flex') {
    overlay.style.display = 'none';
    gameStarted = true;
    startGameLoop();
    return;
  }

  // If game over or start menu visible, ignore input
  if (gameOverState || startMenu.style.display !== 'none') return;

  // Direction controls
  switch (e.key) {
    case 'ArrowUp':
    case 'w':
    case 'W':
      if (!isOpposite(DIR.UP, direction)) nextDirection = DIR.UP;
      break;
    case 'ArrowDown':
    case 's':
    case 'S':
      if (!isOpposite(DIR.DOWN, direction)) nextDirection = DIR.DOWN;
      break;
    case 'ArrowLeft':
    case 'a':
    case 'A':
      if (!isOpposite(DIR.LEFT, direction)) nextDirection = DIR.LEFT;
      break;
    case 'ArrowRight':
    case 'd':
    case 'D':
      if (!isOpposite(DIR.RIGHT, direction)) nextDirection = DIR.RIGHT;
      break;
  }
}

// ─── Start Game Button ──────────────────────────────────────

startBtn.addEventListener('click', () => {
  // Get board size from input
  const inputVal = parseInt(boardSizeInput.value, 10);
  if (!isNaN(inputVal) && inputVal >= 10) {
    configuredBoardSize = inputVal;
  } else {
    configuredBoardSize = 20;
  }

  // Show game area, reset game, show overlay
  showGameArea();
  resetGame();
  overlay.style.display = 'flex';
  gameStarted = false;
});

// ─── Play Again Button ──────────────────────────────────────

playAgainBtn.addEventListener('click', () => {
  gameOverDiv.style.display = 'none';
  // Return to start menu
  showStartMenu();
  resetGame();
});

// ─── Window Resize Handler ──────────────────────────────────

window.addEventListener('resize', () => {
  // Only recompute if game area is visible (not during active gameplay)
  if (!gameRunning && !gameOverState && gameArea.style.display !== 'none') {
    computeBoardDimensions();
    render();
  }
});

// ─── Event Listeners ────────────────────────────────────────
document.addEventListener('keydown', handleKeyDown);

// ─── Expose game state on `window` for debugging/testing ────
window.snakeGame = {
  getSnake: () => [...snake],
  getDirection: () => direction,
  getNextDirection: () => nextDirection,
  setDirection: (d) => {
    // Only allow direction change if not opposite (same rule as keyboard input)
    if (!(d.x === -direction.x && d.y === -direction.y)) {
      nextDirection = d;
    }
  },
  getFood: () => ({ ...food }),
  getScore: () => score,
  getSessionHighScore: () => sessionHighScore,
  getGameRunning: () => gameRunning,
  getGameStarted: () => gameStarted,
  getGameOverState: () => gameOverState,
  getBoardSize: () => boardSize,
  getCellSize: () => cellSize,
  getConfiguredBoardSize: () => configuredBoardSize,
  tick: tick,
  reset: resetGame,
  startGameLoop: startGameLoop,
};

// ─── Initial State ──────────────────────────────────────────
showStartMenu();

